/**
 * Blackjack Module Solver for Keep Talking and Nobody Explains
 *
 * The helper's picture shows your cards; the defuser's picture (with face-down cards) shows the
 * dealer's up card. Says HIT or STAND by blackjack basic strategy (hit / stand only).
 * A rank fixed by hand teaches the reader that card's shape (kept on this device).
 */
(function () {
  'use strict';

  // ── Reading and solving: bomb_boomed's (window.BombLogic.blackjack, bomb-logic.js) ──
  // Generated by bomb_boomed's scripts/build-conso-logic.mjs: re-run it to sync, don't copy code here.
  const { readBlackjack, encodeShape, RANKS, bjAdvice, bustChance, tableRows, TABLE_DEALERS, rankValue } = window.BombLogic.blackjack;
  const K = window.ModuleKit;
  const { $, esc } = K;

  const SHAPES_KEY = 'ktane_blackjack_shapes'; // rank shapes learned from corrections (JSON)
  const loadLearned = () => { try { return JSON.parse(localStorage.getItem(SHAPES_KEY) || '{}') || {}; } catch (e) { return {}; } };

  const state = {
    player: [], // [{ rank, unsure, thumb, glyph, red }]
    dealer: null,
    status: { text: '', ok: null },
    learned: loadLearned()
  };
  window.blackjackModuleState = state;

  function injectStyles() {
    K.injectBase();
    if ($('blackjackStyles')) return;
    const style = document.createElement('style');
    style.id = 'blackjackStyles';
    style.textContent = `
    .bj-ranks { display: flex; flex-wrap: wrap; gap: 4px; }
    .bj-rank { min-width: 32px; padding: 6px 0; background: #161936; border: 1px solid #2d3366; color: #e2e8f0; border-radius: 7px; font: 800 13px 'Outfit', sans-serif; cursor: pointer; }
    .bj-rank:hover { border-color: #ffd875; color: #ffd875; }
    .bj-card { display: inline-flex; align-items: center; gap: 5px; background: #f8fafc; color: #111; border: 2px solid #cbd5e1; border-radius: 8px; padding: 3px 6px; }
    .bj-card.red select { color: #c0262d; }
    .bj-card.unsure { border-color: #f59e0b; box-shadow: 0 0 0 2px rgba(245,158,11,0.35); }
    .bj-card img { height: 34px; border-radius: 3px; }
    .bj-card select { background: transparent; border: none; font: 900 16px 'Outfit', sans-serif; color: #111; cursor: pointer; }
    .bj-card .mk-x { color: #475569; }
    .bj-check { font-size: 10px; font-weight: 800; color: #b45309; text-transform: uppercase; }
    .bj-answer.HIT { color: #4ade80; } .bj-answer.STAND { color: #60a5fa; }
    .bj-table td.hit { color: #4ade80; font-weight: 700; } .bj-table td.stand { color: #60a5fa; font-weight: 700; }
    .bj-table th.on { color: #ffd875; }
    .bj-table td.cell { outline: 2px solid #ffd875; outline-offset: -2px; }
    `;
    document.head.appendChild(style);
  }

  function renderUI() {
    const section = $('blackjackSection');
    if (!section) return;
    section.innerHTML = `
      <div class="mk-shell">
        <div class="mk-head">
          <div class="mk-title"><span>🃏</span> Blackjack Solver <span class="mk-pill">Hit or Stand</span></div>
          <div class="mk-actions"><button class="mk-btn" type="button" data-act="clear">Reset</button></div>
        </div>
        <div class="mk-layout">
          <div>
            <div class="mk-card">
              <div class="mk-card-title">Paste a Screenshot</div>
              <input type="file" id="blackjackFileInput" accept="image/*" multiple style="display:none;">
              <div id="blackjackDropzone" class="mk-dropzone">
                <div class="mk-drop-icon">🃏</div>
                <div class="mk-drop-title">Click, drop or <kbd>Ctrl+V</kbd> a Blackjack picture</div>
                <div class="mk-drop-sub">helper's picture = <b>your cards</b> · defuser's picture (with face-down cards) = the <b>dealer's up card</b></div>
              </div>
              <div id="blackjackStatus"></div>
              <div class="mk-row"><span class="mk-label">Dealer shows</span><span id="blackjackDealer"></span></div>
              <div class="mk-row"><span class="mk-label">Your cards</span><span id="blackjackPlayer" style="display:flex; flex-wrap:wrap; gap:6px;"></span></div>
              <div class="mk-row"><span class="mk-label" id="blackjackAddLbl">Or tap them</span>${rankButtons('add')}</div>
            </div>
          </div>
          <div>
            <div class="mk-banner">
              <div class="mk-banner-row">
                <div>
                  <div class="mk-banner-lbl">Hit or Stand</div>
                  <div id="blackjackAnswer" class="mk-answer"></div>
                  <div id="blackjackStats" class="mk-stats"></div>
                </div>
                <button id="blackjackCopyBtn" class="mk-btn gold" type="button" data-act="copy">📋 Copy</button>
              </div>
            </div>
            <div id="blackjackAdvice"></div>
            <details class="mk-details">
              <summary>Hit / stand table (basic strategy)</summary>
              <div id="blackjackTable" class="mk-table-wrap"></div>
              <div class="mk-dim" style="margin-top:8px;">Standard blackjack basic strategy with only hit / stand. An ace counts 11 unless that busts (then it's a "soft" hand). 10, J, Q, K are all 10.</div>
            </details>
          </div>
        </div>
      </div>`;
    K.wirePictures({ sectionId: 'blackjackSection', dropzoneId: 'blackjackDropzone', inputId: 'blackjackFileInput', onPictures: readPictures });
    section.addEventListener('click', onClick);
    section.addEventListener('change', onChange);
    update();
  }

  function rankButtons(act) {
    return `<span class="bj-ranks">${RANKS.map(r => `<button type="button" class="bj-rank" data-act="${act}" data-rank="${r}">${r}</button>`).join('')}</span>`;
  }

  function chip(card, who, i) {
    return `<span class="bj-card ${card.red ? 'red' : ''} ${card.unsure ? 'unsure' : ''}" title="${card.unsure ? 'Not sure about this rank — check it' : ''}">
      ${card.thumb ? `<img src="${card.thumb}" alt="">` : ''}
      <select data-act="rank" data-who="${who}" data-i="${i}" aria-label="${who === 'dealer' ? 'dealer card' : `card ${i + 1}`}">
        ${card.rank ? '' : '<option value="">?</option>'}${RANKS.map(r => `<option${r === card.rank ? ' selected' : ''}>${r}</option>`).join('')}
      </select>
      ${card.unsure ? '<span class="bj-check">check</span>' : ''}
      <button type="button" class="mk-x" data-act="remove" data-who="${who}" data-i="${i}" aria-label="remove card">✕</button>
    </span>`;
  }

  function cropUri(img, b, pad = 2) {
    const c = document.createElement('canvas');
    const w = b.x1 - b.x0 + pad * 2, h = Math.round((b.y1 - b.y0) * 0.55) + pad * 2; // the top half: rank + suit
    c.width = w; c.height = h;
    c.getContext('2d').drawImage(img, b.x0 - pad, b.y0 - pad, w, h, 0, 0, w, h);
    return c.toDataURL();
  }

  const cardFrom = (img, c) => ({
    rank: c.rank, red: c.red, glyph: c.glyph, thumb: cropUri(img, c.box),
    unsure: !c.rank || c.score < 0.6 || c.margin < 0.1
  });

  function readPictures(items) {
    for (const { img } of items) readOne(img);
    update();
  }

  function readOne(img) {
    let r;
    try {
      const d = K.imageData(img, 2400);
      r = readBlackjack(d.data, d.width, d.height, state.learned);
    } catch (e) {
      state.status = { text: `Could not read that image (${e.message || e}).`, ok: false };
      return;
    }
    if (!r.ok) { state.status = { text: `${r.reason} — is this a Blackjack screenshot?`, ok: false }; return; }
    if (r.defuser) {
      // the defuser's screen: the dealer's up card is the face-up card in the top row
      const c = r.faceUp.find(x => x.row === 0) || r.faceUp[0];
      if (!c) { state.status = { text: `Defuser's screen, but no face-up card (${r.faceDown} face down).`, ok: false }; return; }
      const card = cardFrom(img, c);
      state.dealer = card;
      state.status = { text: `Defuser's screen: dealer shows ${card.rank || '?'}${card.unsure ? ' (check it)' : ''} · ${r.faceDown} card${r.faceDown === 1 ? '' : 's'} face down`, ok: !card.unsure };
    } else {
      const cards = r.faceUp.map(c => cardFrom(img, c));
      state.player = cards;
      state.status = { text: `Helper's cards: ${cards.map(c => c.rank || '?').join(' + ')}${cards.some(c => c.unsure) ? ' · check the marked card' : ''}`, ok: !cards.some(c => c.unsure) };
    }
  }

  // a corrected rank teaches the reader that shape
  function learn(card, rank) {
    if (!card || !card.glyph || card.rank === rank) return;
    state.learned = { ...state.learned, [rank]: [encodeShape(card.glyph.v), ...(state.learned[rank] || [])].slice(0, 4) };
    try { localStorage.setItem(SHAPES_KEY, JSON.stringify(state.learned)); } catch (e) { /* private mode */ }
  }

  function onClick(e) {
    const b = e.target.closest('[data-act]');
    if (!b || b.tagName === 'SELECT') return;
    const act = b.dataset.act;
    if (act === 'add') {
      state.player = [...state.player, { rank: b.dataset.rank }];
    } else if (act === 'dealer') {
      state.dealer = { rank: b.dataset.rank };
    } else if (act === 'remove') {
      if (b.dataset.who === 'dealer') state.dealer = null;
      else state.player = state.player.filter((_, j) => j !== Number(b.dataset.i));
    } else if (act === 'copy') {
      K.copyText(currentAnswer(), b, '📋 Copy');
      return;
    } else if (act === 'clear') {
      state.player = []; state.dealer = null; state.status = { text: '', ok: null };
    } else return;
    update();
  }

  function onChange(e) {
    const s = e.target;
    if (s.dataset.act !== 'rank') return;
    const rank = s.value;
    if (s.dataset.who === 'dealer') {
      learn(state.dealer, rank);
      state.dealer = { ...(state.dealer || {}), rank, unsure: false };
    } else {
      const i = Number(s.dataset.i);
      learn(state.player[i], rank);
      state.player = state.player.map((c, j) => (j === i ? { ...c, rank, unsure: false } : c));
    }
    update();
  }

  function advice() {
    return bjAdvice(state.player.map(c => c.rank).filter(Boolean), state.dealer && state.dealer.rank);
  }
  function currentAnswer() {
    const a = advice();
    return a && a.action ? a.action : '';
  }

  function tableHtml(a) {
    const rows = tableRows();
    const dv = state.dealer && state.dealer.rank ? rankValue(state.dealer.rank) : null;
    let hi = -1;
    if (a && !a.bust) {
      hi = a.soft
        ? rows.findIndex(r => r.soft && (a.total >= 19 ? r.total === 19 : a.total === 18 ? r.total === 18 : r.total === 17))
        : rows.findIndex(r => !r.soft && (a.total <= 11 ? r.total === 11 : a.total >= 17 ? r.total === 17 : r.total === a.total));
    }
    return `<table class="mk-table bj-table"><thead><tr><th>you \\ dealer</th>${TABLE_DEALERS.map(d => `<th class="${dv === d ? 'on' : ''}">${d === 11 ? 'A' : d}</th>`).join('')}</tr></thead><tbody>${
      rows.map((r, i) => `<tr class="${i === hi ? 'on' : ''}"><th>${esc(r.label)}</th>${r.cells.map((x, j) => `<td class="${x === 'HIT' ? 'hit' : 'stand'} ${i === hi && dv === TABLE_DEALERS[j] ? 'cell' : ''}">${x === 'HIT' ? 'H' : 'S'}</td>`).join('')}</tr>`).join('')
    }</tbody></table>`;
  }

  function update() {
    if (!$('blackjackAnswer')) return;
    const ranks = state.player.map(c => c.rank).filter(Boolean);
    const a = advice();
    const answer = a && a.action ? a.action : '';
    const unsure = state.player.some(c => c.unsure) || (state.dealer && state.dealer.unsure);

    $('blackjackStatus').innerHTML = state.status.text ? `<div class="mk-status ${state.status.ok === false ? 'bad' : state.status.ok ? 'ok' : ''}">${esc(state.status.text)}</div>` : '';
    $('blackjackDealer').innerHTML = state.dealer ? chip(state.dealer, 'dealer', 0) : rankButtons('dealer');
    $('blackjackPlayer').innerHTML = state.player.map((c, i) => chip(c, 'player', i)).join('');
    $('blackjackAddLbl').textContent = state.player.length ? '+ Add a card' : 'Or tap them';

    $('blackjackAnswer').innerHTML = answer
      ? `<span class="bj-answer ${answer}">${answer}</span>`
      : `<span class="ph">${a && a.bust ? 'BUST' : '— — —'}</span>`;
    $('blackjackStats').textContent = a ? `${a.soft ? 'soft ' : ''}${a.total}${state.dealer && state.dealer.rank ? ` vs ${state.dealer.rank}` : ''}` : 'Paste the helper\'s cards and the defuser\'s screen, or tap the ranks.';
    $('blackjackAdvice').innerHTML = a ? `<div class="mk-note ${unsure ? 'mk-warn' : ''}">${
      esc(a.needsDealer ? 'Paste the defuser\'s screen (or tap the dealer\'s card) — this one depends on it.' : a.why)
    }${!a.bust ? ` · if you hit: ${Math.round(bustChance(ranks) * 100)}% chance to bust` : ''}${unsure ? ' · ⚠ a card rank is marked "check"' : ''}</div>` : '';
    $('blackjackTable').innerHTML = tableHtml(a);
  }

  window.initBlackjackModule = function () {
    injectStyles();
    renderUI();
  };
})();
